def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))
    marker = min((x for x in set(v for row in grid for v in row) if x != bg),
                 key=lambda x: sum(row.count(x) for row in grid))
    coords = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, marker)]
    r0, r1 = min(r for r, c in coords), max(r for r, c in coords)
    c0, c1 = min(c for r, c in coords), max(c for r, c in coords)

    if r1 - r0 >= c1 - c0:
        seq = [grid[r][c0] for r in range(r0, r1 + 1)]
        dr, dc = 1, 0
    else:
        seq = [grid[r0][c] for c in range(c0, c1 + 1)]
        dr, dc = 0, 1

    out = [row[:] for row in grid]
    mid = len(seq) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, color in enumerate(seq):
                    rr, cc = r + (i - mid) * dr, c + (i - mid) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
